// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ANCHToken} from "../src/ANCHToken.sol";

contract InvMutTest is Test {
    ANCHToken c;

    function setUp() public {
        c = new ANCHToken(address(new __InvMutHandleStub()), address(this));
    }

    function testFuzz_property(address newOwner) public {
        // Only a non-zero, distinct target is admissible; the deployer (address(this))
        // is the caller, so ownership transferring to it is indistinguishable from the bug.
        vm.assume(newOwner != address(0));
        vm.assume(newOwner != address(this));

        // The current owner (deployer) drives changeOwner.
        vm.prank(address(this));
        c.changeOwner(newOwner);

        // Rule: for every admissible input, the owner after the call is exactly newOwner.
        assertTrue(c.owner() == newOwner, "owner must equal the requested newOwner");
    }
}

contract __InvMutHandleStub {
    function factory() external view returns (address) { return address(this); }
    function createPair(address, address) external view returns (address) { return address(this); }
    function underlying() external view returns (address) { return address(this); }
    function WETH() external view returns (address) { return address(this); }
    function name() external pure returns (string memory) { return "S"; }
    function symbol() external pure returns (string memory) { return "S"; }
